@startuml

class ProjectManager {
  + Name : string
}

class Project {
  + StartDate : date
  + EndDate : date
  + Initiate() : void
  + Terminate() : void
}

abstract class WorkProduct {
  + Description : string
  + PercentComplete : float
  + Validate() : void
}

class Requirement extends WorkProduct {
  + ValidateWithUsersInWorkshops() : void
}

class System extends WorkProduct {
  + ValidateAgainstRequirements() : void
}

class RequirementPublication {
  + Media : string
}

class Deployment {
  + Platform : string
}

ProjectManager "1" -- "1" Project : leads
Project "1" -- "*" Requirement : uses
Project "1" -- "0..*" System : produces
Requirement "1" -- "0..*" RequirementPublication : is published via
System "1" -- "0..*" Deployment : is deployed onto

@enduml

